#include "../local_economy_codec_detail.hpp"
namespace hanmo::resident::dynamic_economy_codec {
template<> struct EnumNames<NeedMeasure>{inline static constexpr std::pair<NeedMeasure,const char*> names[]={{NeedMeasure::stock_gap,"stock_gap"},{NeedMeasure::cumulative_delivery,"cumulative_delivery"}};static constexpr const auto& rows(){return names;}};
// 复用S3原NeedPolicy类型，仅本新段的Codec声明，不改其旧目录与存档布局。
template<class A>void record(A& a,NeedPolicy& v){a("id",v.id);a("source_domain",v.source_domain);a("source_key",v.source_key);a("semantic_key",v.semantic_key);a("organization_id",v.organization_id);a("site_id",v.site_id);a("inventory_id",v.inventory_id);a("item_id",v.item_id);a("unit",v.unit);a("template_id",v.template_id);a("terms_version",v.terms_version);a("funding_wallet_id",v.funding_wallet_id);a("reward_wallet_id",v.reward_wallet_id);a("measure",v.measure);a("max_claim_quantity",v.max_claim_quantity);a("purchase_budget_per_unit",v.purchase_budget_per_unit);a("reward_per_unit",v.reward_per_unit);a("deadline_ticks",v.deadline_ticks);a("accept_role",v.accept_role);a("report_role",v.report_role);a("cancellation_policy_id",v.cancellation_policy_id);a("reward_total",v.reward_total);}
template<class A>void record(A& a,EconomicSupplyPolicyDefinition& v){a("id",v.id);a("original_source_key",v.original_source_key);a("organization_id",v.organization_id);a("template_id",v.template_id);a("terms_version",v.terms_version);a("unit",v.unit);a("funding_wallet_id",v.funding_wallet_id);a("reward_wallet_id",v.reward_wallet_id);a("accept_role",v.accept_role);a("report_role",v.report_role);a("measure",v.measure);a("target_amount",v.target_amount);a("max_claim_quantity",v.max_claim_quantity);a("purchase_budget_per_unit",v.purchase_budget_per_unit);a("reward_per_unit",v.reward_per_unit);a("deadline_ticks",v.deadline_ticks);a("valid_ticks",v.valid_ticks);a.authored_optional("reward_total",v.reward_total);a("public_report",v.public_report);}
template<class A>void record(A& a,EconomicSupplyPolicyCatalog& v){a("version",v.version);a("policies",v.policies);}
template<class A>void record(A& a,EconomicSupplyPolicyRecord& v){a("id",v.id);a("author_policy_id",v.author_policy_id);a("registration_fact_id",v.registration_fact_id);a("original_source_key",v.original_source_key);a("original_source_fact_id",v.original_source_fact_id);a("grant_id",v.grant_id);a("authority",v.authority);a("policy",v.policy);a("issued_tick",v.issued_tick);a("earliest_effective_tick",v.earliest_effective_tick);a("through_tick",v.through_tick);a("target_amount",v.target_amount);a("public_report",v.public_report);}
template<class A>void record(A& a,EconomicSupplyPolicyObservation& v){a("policy_fact_id",v.policy_fact_id);a("observation",v.observation);}
template<class A>void record(A& a,EconomicSupplyPolicyState& v){a("version",v.version);a("initialized_tick",v.initialized_tick);a("last_observation_tick",v.last_observation_tick);a("policies",v.policies);a("observations",v.observations);}
}
